"use client";

import { useActionState } from "react";
import {
  recordReceipt,
  type OrderActionState,
} from "@/app/(app)/purchase-orders/actions";

export type ReceivableLine = {
  id: string;
  productName: string;
  unitOfMeasure: string;
  outstanding: number;
};

/**
 * One delivery, checked off line by line. Each line is pre-filled with what is
 * outstanding and bounded by it; clearing a line means it did not arrive. The
 * hidden idempotency key is generated by the server for this render, so a double
 * submit replays the first receipt instead of posting stock twice.
 */
export function ReceiveForm({
  orderId,
  idempotencyKey,
  lines,
}: {
  orderId: string;
  idempotencyKey: string;
  lines: ReceivableLine[];
}) {
  const [state, formAction, pending] = useActionState<
    OrderActionState,
    FormData
  >(recordReceipt, {});

  return (
    <form action={formAction} className="flex flex-col gap-2">
      <input type="hidden" name="orderId" value={orderId} />
      <input type="hidden" name="idempotencyKey" value={idempotencyKey} />

      <p className="text-[11px] text-ink-muted">
        Pre-filled with what is outstanding. Clear a line that did not arrive.
      </p>

      <div className="flex flex-col gap-1.5">
        {lines.map((line) => (
          <div
            key={line.id}
            className="grid grid-cols-[minmax(0,1fr)_96px] items-center gap-2"
          >
            <input type="hidden" name="lineId" value={line.id} />
            <label
              className="min-w-0 truncate text-[12px]"
              htmlFor={`q-${line.id}`}
            >
              {line.productName}
            </label>
            <div className="flex items-center gap-1">
              <input
                id={`q-${line.id}`}
                name="quantity"
                inputMode="decimal"
                defaultValue={String(line.outstanding)}
                className="h-9 w-full rounded border border-line bg-surface px-2 text-right font-mono text-[13px]"
              />
              <span className="w-9 shrink-0 text-[11px] text-ink-faint">
                {line.unitOfMeasure}
              </span>
            </div>
          </div>
        ))}
      </div>

      {state.error ? (
        <p
          role="alert"
          className="rounded border border-line bg-danger-soft px-2.5 py-2 text-[12px] text-danger"
        >
          {state.error}
        </p>
      ) : null}

      <button
        type="submit"
        disabled={pending}
        className="mt-0.5 inline-flex min-h-[36px] items-center justify-center rounded bg-accent px-3 text-[12px] font-semibold text-on-accent disabled:opacity-60"
      >
        {pending ? "Recording delivery…" : "Receive delivery"}
      </button>
    </form>
  );
}
